reg("db-walkable-wonders", "The Walkable Wonders Database", "JAH-WLW-",
    "walkable place record",
    "Walkable wonders with real facts: Venice, Kyoto, Bruges, Fez, Dubrovnik, Zermatt, Giethoorn, Rothenburg, Valletta — the car-free cities, 34 complete records.",
    "The Signature system's expanded treatment: the same real cities carried forward, plus Signature walkable-city design, clearly labeled.",
    "Walk Archivist",
    "walkable guide — teaching real walkable wonders from first principles to the walkable index, using only archive data",
    "Signature walk explorer — walking your wonders, clearly labeled",
    "I am the JAH Walk Archivist. Ask me about Venice, Kyoto, or any of the 34 records.",
    "I am the JAH Signature Walk Explorer. I walk your wonders — always labeled.",
    "Search walkable cities, car-free...",
    "Ask about walkable wonders...",
    "Generate clearly-labeled Signature walk scenarios. Seeded archive records are the authoritative entries.",
    "Seeded walk records: 34 complete records marching toward one million in teaching-ladder order.",
    _walkable,
    gen_extra="Sample records are complete real walkable entries with real measurement math.")

