reg("db-lighthouse-explorer", "The Lighthouse Explorer Database", "JAH-LHX-",
    "lighthouse record",
    "Lighthouses with real facts: Peggy's Cove, Lindau, Portland Head, Formentor, Split Rock, Cape Hatteras, Fastnet, Jeddah, Tourlitis — the beacons, 34 complete records.",
    "The Signature system's expanded treatment: the same real beacons carried forward, plus Signature lighthouse-tour design, clearly labeled.",
    "Lighthouse Archivist",
    "lighthouse guide — teaching real lighthouses from first principles to the lighthouse index, using only archive data",
    "Signature lighthouse explorer — climbing your beacons, clearly labeled",
    "I am the JAH Lighthouse Archivist. Ask me about Peggy's Cove, Fastnet, or any of the 34 records.",
    "I am the JAH Signature Lighthouse Explorer. I climb your beacons — always labeled.",
    "Search lighthouses, beacons...",
    "Ask about lighthouses...",
    "Generate clearly-labeled Signature lighthouse scenarios. Seeded archive records are the authoritative entries.",
    "Seeded lighthouse records: 34 complete records marching toward one million in teaching-ladder order.",
    _lighthouse,
    gen_extra="Sample records are complete real lighthouse entries with real measurement math.")

