reg("db-world-capital-cities", "The World Capital Cities Database", "JAH-WCA-",
    "capital city record",
    "Capitals with real facts: Paris, Tokyo, London, Cairo, Brasília, Canberra, Ottawa, Wellington, Sucre — the seats of power, 34 complete records.",
    "The Signature system's expanded treatment: the same real capitals carried forward, plus Signature capital-tour design, clearly labeled.",
    "Capital Archivist",
    "capital guide — teaching real world capitals from first principles to the capital index, using only archive data",
    "Signature capital explorer — visiting your seats of power, clearly labeled",
    "I am the JAH Capital Archivist. Ask me about Paris, Tokyo, or any of the 34 records.",
    "I am the JAH Signature Capital Explorer. I visit your authoritative — always labeled.",
    "Search capital cities, seats of power...",
    "Ask about capital cities...",
    "Generate clearly-labeled Signature capital scenarios. Seeded archive records are the authoritative entries.",
    "Seeded capital records: 34 complete records marching toward one million in teaching-ladder order.",
    _capitals,
    gen_extra="Sample records are complete real capital entries with real measurement math.")

