reg("db-ultimate-travel-surprise", "The Ultimate Travel Surprise Database", "JAH-USU-",
    "travel surprise record",
    "Travel surprises with real facts: mystery flights, blind boxes, proposal trips, anniversaries, honeymoons, birthdays, graduations — the delightful unknown, 34 complete records.",
    "The Signature system's expanded treatment: the same real surprises carried forward, plus Signature surprise-trip design, clearly labeled.",
    "Surprise Archivist",
    "surprise guide — teaching real ultimate travel surprises from first principles to the surprise index, using only archive data",
    "Signature surprise planner — crafting your delightful unknowns, clearly labeled",
    "I am the JAH Surprise Archivist. Ask me about mystery flights, surprise proposals, or any of the 34 records.",
    "I am the JAH Signature Surprise Planner. I craft your delightful — always labeled.",
    "Search travel surprises, mystery trips...",
    "Ask about travel surprises...",
    "Generate clearly-labeled Signature surprise scenarios. Seeded archive records are the authoritative entries.",
    "Seeded surprise records: 34 complete records marching toward one million in teaching-ladder order.",
    _surprise,
    gen_extra="Sample records are complete real surprise entries with real measurement math.")
